/** Designs whose full-page render replaces the coded storefront. All other designs keep their coded preview. */
const showcaseEnabled = new Set([
  "atelier-bundle-signature",
  "atelier-campaign",
  "atelier-cinematic",
  "atelier-commerce-studio",
  "atelier-concierge-signature",
  "atelier-configurator-signature",
  "atelier-dimensional",
  "atelier-parallax",
]);

export function getShopifyShowcase(referenceId?: string | null): ShopifyShowcase | null {
  return referenceId && showcaseEnabled.has(referenceId) && Object.prototype.hasOwnProperty.call(shopifyShowcases, referenceId) ? shopifyShowcases[referenceId] : null;
}
